quiz.answer:
package main

import (
	"bufio"
	"encoding/base64"
	"fmt"
	"os"
	"strings"
)

// decodePart は Base64URL(パディングなし)の文字列を元の文字列に戻す
func decodePart(s string) (string, error) {
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	token := strings.TrimSpace(sc.Text())

	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		fmt.Println("NG")
		return
	}
	header, err1 := decodePart(parts[0])
	payload, err2 := decodePart(parts[1])
	if err1 != nil || err2 != nil {
		fmt.Println("NG")
		return
	}
	fmt.Println(header)
	fmt.Println(payload)
}
